arguments.command:
cd /tmp && ls -l /tmp/CompCert/ccomp && printf '#include <stdio.h>
int fib(int n){return n<2?n:fib(n-1)+fib(n-2);}
int main(){printf("%%d\n",fib(20));return 0;}
' > t.c && /tmp/CompCert/ccomp -O2 t.c -o t && ./t && /tmp/CompCert/ccomp -v 2>&1|head -2

